from rules import amount


def solve(data):
    balances = dict(data.get('opening', {}))
    cutoff = data.get('cutoff', 10**9)
    selected = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue
        identifier = event.get('id', None)
        key = ('id', identifier) if 'id' in event else ('anonymous', position)
        revision = event.get('revision', 0)
        previous = selected.get(key)
        if previous is None or revision >= previous[0]:
            selected[key] = (revision, position, event)

    for _, _, event in selected.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data.get('rounding', 'half_up'))

    return {'balances': balances}
